        "file": "2007-07-04-Happy-Fourth-of-July-.md",
        "year": "2007",
        "date": "July 04, 2007",
        "title": "Happy Fourth of July!",
        "body": "<img src=\"http://photos1.blogger.com/x/blogger2/4201/1199/320/z/52004/img105-724525.jpg\" width=\"320\"/>\nPosted wirelessly!"
